        assertEquals(true, trans.get((K) "B").contains(Integer.valueOf(2)));
        assertEquals(true, trans.get((K) "C").contains(Integer.valueOf(3)));
        trans.put((K) "D", (V) "4");
        assertEquals(true, trans.get((K) "D").contains(Integer.valueOf(4)));
    }

