        return locale;
    }

@Parameters(name = "{0}")
    public static Locale[] getSortedAvailableLocales() {
        final Locale[] availableLocales = Locale.getAvailableLocales();
        Arrays.sort(availableLocales, new ObjectToStringComparator());
        return availableLocales;
    }

public static List<Locale> getSortedDeclaredLocales() {
        final Field[] allFields = FieldUtils.getAllFields(Locale.class);
        final List<Locale> availableLocales = new ArrayList<>(allFields.length);
        for (final Field field : allFields) {
            final int modifiers = field.getModifiers();
            if (field.getType() == Locale.class && Modifier.isStatic(modifiers) && Modifier.isPublic(modifiers)) {
                try {
                    availableLocales.add((Locale) field.get(Locale.class));
                } catch (IllegalArgumentException | IllegalAccessException e) {
                    throw new IllegalStateException("Field " + field, e);
                }
            }
        }
        Collections.sort(availableLocales, new ObjectToStringComparator());
        return availableLocales;
    }

public Locale getLocale() {
        return locale;
    }

@Override
    public int compare(final Object o1, final Object o2) {
        if (o1 == null && o2 == null) {
            return 0;
        }
        if (o1 == null) {
            return 1;
        }
        if (o2 == null) {
            return -1;
        }
        return o1.toString().compareTo(o2.toString());
    }

@Override
    public void verify() {
        super.verify();

        // Check that iterator returns elements in order and first() and last()
        // are consistent
        final Iterator<T> colliter = getCollection().iterator();
        final Iterator<T> confiter = getConfirmed().iterator();
        T first = null;
        T last = null;
        while (colliter.hasNext()) {
            if (first == null) {
                first = colliter.next();
                last = first;
            } else {
              last = colliter.next();
            }
            assertEquals("Element appears to be out of order.", last, confiter.next());
        }
        if (getCollection().size() > 0) {
            assertEquals("Incorrect element returned by first().",first,getCollection().first());
            assertEquals("Incorrect element returned by last().",last,getCollection().last());
        }
    }

